import React, { useState, useEffect } from "react";
import axios from "axios";
import { useNavigate } from "react-router-dom";
import "bootstrap/dist/css/bootstrap.min.css";

const Home = () => {
  const [cursos, setCursos] = useState([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState(null);
  const [isAuthenticated, setIsAuthenticated] = useState(false);
  const navigate = useNavigate();

  const [comentarios, setComentarios] = useState([]);
  const [showComentarioModal, setShowComentarioModal] = useState(false);
  const [novoComentario, setNovoComentario] = useState("");

  useEffect(() => {
    const fetchCursos = async () => {
      try {
        const response = await axios.get("http://localhost:5000/cursos");
        setCursos(response.data);
        setLoading(false);
      } catch (err) {
        setError(err.message);
        setLoading(false);
      }
    };

    // Verificar autenticação
    const checkAuth = () => {
      const token = localStorage.getItem("token");
      if (token) {
        setIsAuthenticated(true);
      }
    };

    fetchCursos();
    checkAuth();
  }, []);

  // Adicione este useEffect para carregar os comentários
  useEffect(() => {
    const fetchComentarios = async () => {
      try {
        const response = await axios.get("http://localhost:5000/comentarios");
        setComentarios(response.data);
      } catch (err) {
        console.error("Erro ao carregar comentários:", err);
      }
    };

    fetchComentarios();
  }, []);

  // Função para enviar novo comentário
  const handleSubmitComentario = async () => {
    try {
      const response = await axios.post(
        "http://localhost:5000/comentarios",
        { conteudo: novoComentario },
        {
          headers: {
            Authorization: `Bearer ${localStorage.getItem("token")}`,
          },
        }
      );

      setComentarios([response.data, ...comentarios]);
      setNovoComentario("");
      setShowComentarioModal(false);
    } catch (err) {
      console.error("Erro ao enviar comentário:", err);
      if (err.response && err.response.status === 401) {
        navigate("/login", { state: { from: "/" } });
      }
    }
  };

  // Modifique a seção de testemunhos para incluir os comentários dinâmicos
  <div className="col-md-6 bg-white p-4 rounded shadow">
    <h4>Testemunhos de Alunos:</h4>
    {comentarios.map((comentario) => (
      <div key={comentario.id} className="mb-3">
        <h5>{comentario.aluno.utilizador.nome}:</h5>
        <p>{comentario.conteudo}</p>
        <small className="text-muted">
          {new Date(comentario.dataPublicacao).toLocaleDateString("pt-PT")}
        </small>
      </div>
    ))}

    <div>
      <input
        type="checkbox"
        id="comentario"
        checked={showComentarioModal}
        onChange={() => {
          if (isAuthenticated) {
            setShowComentarioModal(!showComentarioModal);
          } else {
            navigate("/login", { state: { from: "/" } });
          }
        }}
      />
      <label htmlFor="comentario"> Deixa um comentário</label>
    </div>

    {/* Modal para novo comentário */}
    {showComentarioModal && (
      <div
        className="modal"
        style={{ display: "block", backgroundColor: "rgba(0,0,0,0.5)" }}
      >
        <div className="modal-dialog">
          <div className="modal-content">
            <div className="modal-header">
              <h5 className="modal-title">Novo Comentário</h5>
              <button
                type="button"
                className="btn-close"
                onClick={() => setShowComentarioModal(false)}
              ></button>
            </div>
            <div className="modal-body">
              <textarea
                className="form-control"
                rows="4"
                value={novoComentario}
                onChange={(e) => setNovoComentario(e.target.value)}
                placeholder="Escreva seu comentário aqui..."
              ></textarea>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setShowComentarioModal(false)}
              >
                Cancelar
              </button>
              <button
                type="button"
                className="btn btn-primary"
                onClick={handleSubmitComentario}
                disabled={!novoComentario.trim()}
              >
                Enviar
              </button>
            </div>
          </div>
        </div>
      </div>
    )}
  </div>;

  const handleProtectedLink = (path) => {
    if (isAuthenticated) {
      navigate(path);
    } else {
      navigate("/login", { state: { from: path } });
    }
  };

  // Agrupa cursos por área
  const cursosPorArea = cursos.reduce((acc, curso) => {
    if (!acc[curso.area]) {
      acc[curso.area] = [];
    }
    acc[curso.area].push(curso);
    return acc;
  }, {});

  if (loading) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="spinner-border" role="status">
          <span className="visually-hidden">Carregando...</span>
        </div>
      </div>
    );
  }

  if (error) {
    return (
      <div className="container-fluid text-center mt-5">
        <div className="alert alert-danger">
          Erro ao carregar cursos: {error}
        </div>
      </div>
    );
  }

  return (
    <div
      className="container-fluid"
      style={{
        backgroundColor: "#F8F9FA",
        minHeight: "100vh",
        padding: "20px",
      }}
    >
      <nav className="d-flex justify-content-end p-3">
        <a href="." className="mx-2">
          Home
        </a>
        <a href="./about" className="mx-2">
          About
        </a>
        <a href="./faq" className="mx-2">
          Faq
        </a>
        <a href="./contact" className="mx-2">
          Contacto
        </a>
        <a href="./login" className="mx-2">
          Login
        </a>
        <a href="./register" className="mx-2">
          Registo
        </a>
      </nav>
      <h1>EducaWeb</h1>

      {/* Seção de Cursos */}
      <div className="row mt-4">
        {Object.entries(cursosPorArea).map(([area, cursosDaArea]) => (
          <div className="col-md-6 mb-4" key={area}>
            <div className="card h-100">
              <div className="card-body">
                <h2 className="card-title">
                  {area} {getEmojiForArea(area)}
                </h2>
                <ul className="list-group list-group-flush">
                  {cursosDaArea.map((curso) => (
                    <li className="list-group-item" key={curso.id}>
                      <strong>{curso.nome}</strong>
                      <div className="text-muted small mt-1">
                        {curso.periodo} | Nível {curso.nivel}
                      </div>
                      <div className="text-muted small">
                        {formatDate(curso.dataInicio)} -{" "}
                        {formatDate(curso.dataFim)}
                      </div>
                    </li>
                  ))}
                </ul>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* Restante do seu conteúdo */}
      <div className="row mt-5">
        <div className="col-md-6 bg-white p-4 rounded shadow">
          <h4>Lucas Pedro:</h4>
          <p>
            Conteúdo excelente e plataforma super intuitiva! Aprender aqui é um
            prazer.
          </p>
          <h4>Rafael Santos:</h4>
          <p>
            EducaWeb me ajudou a crescer profissionalmente. Recomendo a todos!
          </p>
          <div>
            <input type="checkbox" id="comentario" />
            <label htmlFor="comentario"> Deixa um comentário</label>
          </div>
        </div>
        <div className="col-md-6 bg-white p-4 rounded shadow">
          <div className="list-group">
            {/* Link para Cursos (não requer autenticação) */}
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => navigate("/cursos")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📦 Cursos
            </button>

            {/* Links protegidos (requerem autenticação) */}
            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-ao-vivo")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📚 Aulas ao Vivo
            </button>

            <button
              className="list-group-item list-group-item-action border-0 text-start p-0 mb-2"
              onClick={() => handleProtectedLink("/aulas-gravadas")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📺 Aulas Gravadas
            </button>

            <button
              className="list-group-item list-group-item-action border-0 text-start p-0"
              onClick={() => handleProtectedLink("/material")}
              style={{
                background: "none",
                border: "none",
                textDecoration: "underline",
                color: "#0d6efd",
                cursor: "pointer",
              }}
            >
              📂 Material de Apoio
            </button>
          </div>
        </div>
      </div>
    </div>
  );
};

// Funções auxiliares
function getEmojiForArea(area) {
  const emojis = {
    Economia: "📉",
    Programacao: "💻",
    Contabilidade: "📊",
    Ingles: "📖",
    Matematica: "🧮",
    Design: "🎨",
  };
  return emojis[area] || "📚";
}

function formatDate(dateString) {
  const options = { year: "numeric", month: "short", day: "numeric" };
  return new Date(dateString).toLocaleDateString("pt-PT", options);
}

export default Home;
